code_sketch:
var ch = Channel.CreateBounded<Job>(new BoundedChannelOptions(1000) {
    FullMode = BoundedChannelFullMode.Wait });

await ch.Writer.WriteAsync(job);     // awaits while the channel is full
ch.Writer.Complete();                // end of stream

await foreach (var job in ch.Reader.ReadAllAsync())
    await HandleAsync(job);

